def check_p(p):
    # We check 3^(4p) mod (8p) for k=1
    modulus = 8 * p
    exponent = 4 * p

    if p == 3:
        # Handle p=3 case where gcd(3, 24) != 1
        return f"p={p} fails immediately because gcd(3, {modulus}) = 3 > 1."

    try:
        result = pow(3, exponent, modulus)
        if result == 1:
            return f"p={p} holds for n=1 condition: 3^{exponent} mod {modulus} = 1."
        else:
            return f"p={p} fails for n=1 condition: 3^{exponent} mod {modulus} = {result} != 1."
    except ValueError as e:
        return f"p={p} resulted in an error: {e}"

print(check_p(2))
print(check_p(3))
print(check_p(5))
